using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static List<int> Positives(IEnumerable<int> values)
    {
        return values.Where(value => value > 0).ToList();
    }

    static void Main()
    {
        Console.WriteLine(string.Join(",", Positives(new[] { 3, -1, 2 })));
    }
}
